import {Link, useNavigate} from "react-router-dom";




export default function Login(){

     const navigate = useNavigate()

     async function handleSubmit(event){
         event.preventDefault()
         let email = event.target.email.value
	 let password = event.target.password.value
	 if (!email||!password){
              alert("Please fill in the login form")

	 }

         const credentials = {email,password}

         try{
             const response = await fetch("http://localhost:4000/login",{
	         method: "POST",
		 headers:{
                    "Content=Type": "application/json",
		 },
		 body: JSON.stringify(credentials)

	     })
             const data = await response.json()
             if(response.ok){
                alert ("server respone", data)
	        // redirect user
                navigate("/")
             }
             else{
                 alert("Unable to login: " + data)
	     }
	 }
	 catch{
             ("Unable to connect to the server")  
	 }

     }

     return(
         <div className = "container my-4">
	     <div className="mx-auto rounded border p-4" style={{width:"400px"}}>
	         <h2 className="text-center mb-3">Welcome, please login</h2>

	         <form onSubmit={handleSubmit}>
	             <div className="mb-3">
	                 <label className = "form-label">Email</label>
	                 <input className = "form-control" name="email" />
	             </div>

	             <div className="mb-3">
                         <label className = "form-label">Password</label>
                         <input className = "form-control" name="password" />
                     </div>

	             <div className="row">
	                 <div className="col d-grid">
                             <button type="submit" className = "btn btn-primary">Login</button>
                         </div>

	                 <div className="col d-grid">
                             <Link className = "btn btn-outline-primary" to="/" role="button">Cancel</Link>
                         </div>
                     </div>

	         </form>
	     </div>
	 </div>
     )
}
